  if(!r){if(bar)bar.hidden=true;return}
  const g=el("g",{class:"route","pointer-events":"none"},map);if(pinLayer)map.insertBefore(g,pinLayer);const d="M"+r.pts.map(p=>p.x.toFixed(1)+" "+p.y.toFixed(1)).join("L");
