  el("path",{d,fill:"none",stroke:"var(--pdeep)","stroke-width":5,"stroke-linecap":"round","stroke-linejoin":"round","stroke-dasharray":"0.1 11","vector-effect":"non-scaling-stroke"},g);
  el("circle",{cx:r.a.x,cy:r.a.y,r:5,fill:"#fff",stroke:"var(--pdeep)","stroke-width":3,"vector-effect":"non-scaling-stroke"},g);
  const sp=el("image",{href:"app/sparko.webp",width:40,height:29,class:"skinned"},g);
  // place Sparko along the path at a fraction t (constant on-screen size, like the pins)
  const at=t=>{let L=t*r.len;for(let k=1;k<r.pts.length;k++){const p=r.pts[k-1],q=r.pts[k],s=Math.hypot(q.x-p.x,q.y-p.y);if(L<=s||k===r.pts.length-1){const f=s?Math.min(1,L/s):0;return{x:p.x+(q.x-p.x)*f,y:p.y+(q.y-p.y)*f,dir:q.x<p.x?-1:1}}L-=s}return r.pts[0]};
  const place=t=>{const rc=map.getBoundingClientRect(),k=rc.width?V.w/rc.width:1,p=at(t);sp.setAttribute("transform",`translate(${p.x} ${p.y}) scale(${k*p.dir} ${k}) translate(-20 -27)`)};
